      <span class="cs-art fx-finish"${M(J)}><img alt="" loading="lazy" decoding="async" src="${Sa(J.small)}" srcset="${Sa(J.small)} 146w, ${Sa(J.image)} 488w" sizes="(max-width: 640px) 44vw, 172px" draggable="false"/>${W?'<span class="cs-inuse">✓ In use</span>':J.id===se?'<span class="cs-own">Default</span>':""}</span>
